mapper.select:
SELECT DISTINCT COUNT(1) AS CNT FROM EXPLOIT.SORDERQ AS SORDERQ INNER JOIN EXPLOIT.SORDERP AS SORDERP ON SORDERP.SOHNUM_0 = SORDERQ.SOHNUM_0 AND SORDERP.SOPLIN_0 = SORDERQ.SOPLIN_0 AND SORDERQ.SALFCY_0 = SORDERP.SALFCY_0
AND SORDERP.SALFCY_0 IN ('ZHU','HKG','YSH')
AND SORDERP.SALFCY_0 = #{Site}
AND SORDERQ.SOQSTA_0 != 3
AND (SORDERQ.YSOH_PJT_0 = #{ProjectNO} OR SORDERQ.YSOQ_PJTORI_0 = #{ProjectNO})
INNER JOIN EXPLOIT.SORDER SORDER ON SORDERP.SOHNUM_0 = SORDER.SOHNUM_0 AND SORDER.SALFCY_0 = SORDERP.SALFCY_0
AND SORDER.SOHTYP_0 = 'NOR' AND SORDERQ.YSOQ_STA_0 != 7
AND ( (SORDER.SOHTYP_0 = 'NOR' AND SORDERQ.YSOQ_STA_0 =7) OR SORDER.SOHTYP_0 != 'NOR')
AND SORDER.BPCORD_0 = #{CustomerCode}
INNER JOIN EXPLOIT.PORDERP PORDERP ON (PORDERP.PJT_0 = SORDERQ.YSOH_PJT_0 OR PORDERP.PJT_0 = SORDERQ.YSOQ_PJTORI_0 ) -- this to avoid empty ProjectNO AND SORDERQ.YSOQ_PJTORI_0 != '' AND PORDERP.PRHFCY_0 =SORDERP.SALFCY_0 INNER JOIN EXPLOIT.PORDER AS PORDER ON PORDERP.POHNUM_0=PORDER.POHNUM_0 AND PORDER.POHFCY_0 = SORDERP.SALFCY_0 AND PORDER.BPSNUM_0 = #{VendorCode}
